import { Component, OnInit } from '@angular/core';
import { ToastService, ToastMessage } from '../../../core/services/toast.service';

@Component({
  selector: 'app-toast',
  templateUrl: './toast.component.html',
  styleUrls: ['./toast.component.css']
})
export class ToastComponent implements OnInit {
  toasts: ToastMessage[] = [];

  constructor(private toastService: ToastService) {}

  ngOnInit(): void {
    this.toastService.toasts$.subscribe(toasts => {
      this.toasts = toasts;
    });
  }

  remove(id: string): void {
    this.toastService.remove(id);
  }

  getIcon(type: string): string {
    switch (type) {
      case 'success': return 'fa-solid fa-circle-check';
      case 'error': return 'fa-solid fa-circle-exclamation';
      case 'warning': return 'fa-solid fa-triangle-exclamation';
      case 'info': return 'fa-solid fa-circle-info';
      default: return 'fa-solid fa-bell';
    }
  }
}
<div class="toast-container" *ngIf="toasts.length > 0">
  <div *ngFor="let toast of toasts" class="toast-item" [ngClass]="'toast-' + toast.type">
    <div class="toast-icon">
      <i [class]="getIcon(toast.type)"></i>
    </div>
    <div class="toast-content">
      <h4 class="toast-title">{{ toast.title }}</h4>
      <p class="toast-message">{{ toast.message }}</p>
    </div>
    <button class="toast-close" (click)="remove(toast.id)" aria-label="Close toast">
      <i class="fa-solid fa-xmark"></i>
    </button>
  </div>
</div>
